<template>
  <div class="account-page">
    <div class="section-page-heading"><h2>{{ tr('我的', 'My account') }}</h2></div>
    <section class="panel account-summary">
      <div class="panel-head"><h2>{{ tr('账号', 'Account') }}</h2><RouterLink :to="{path:'/watch',query:{chain:scope}}">{{ tr('我的关注', 'My watchlist') }} →</RouterLink></div>
      <p v-if="!account.ready || account.sessionState==='checking'" role="status" class="hint">{{ tr('正在确认登录状态…','Checking your session…') }}</p>
      <p v-if="account.sessionState==='error'" class="account-error" role="alert">{{ tr('登录状态暂时无法确认，请重试。','Your session could not be checked. Please retry.') }} <button type="button" @click="account.start(true)">{{ tr('重试登录状态','Retry session') }}</button></p>
      <template v-if="account.session">
        <div class="account-identity"><p class="account-email">{{ account.session.user.email }}</p><span>{{ account.watches.length }} {{ tr('个关注','followed items') }}</span><button :disabled="authBusy" @click="signOut">{{ tr('退出登录','Sign out') }}</button></div>
        <p class="account-sync" :class="{'account-error':account.syncState==='error'}" role="status">{{ syncLabel }} <button v-if="account.syncState==='error'" type="button" @click="account.refresh()">{{ tr('重试同步','Retry sync') }}</button></p>
        <RouterLink v-if="account.session.operator" :to="pageNavigationLink('/status',{route,scope})">{{ tr('数据运行状态','Data operations') }} →</RouterLink>
      </template>
      <form v-else-if="account.ready && account.sessionState!=='checking' && account.sessionState!=='error'" class="account-form account-login" @submit.prevent="submit">
        <p class="hint">{{ tr('关注保存在此设备，登录后可同步到账号。','Follows are saved on this device. Sign in to sync them to your account.') }}</p>
        <p v-if="alertTarget" class="hint">{{ tr('登录后可关注','Sign in to follow') }} {{ alertTarget.label }}{{ tr('；提醒规则应用于全部关注。','; alert rules apply to all your followed items.') }}</p>
        <div class="view-tabs"><button type="button" :disabled="authBusy" :class="{active:mode==='login'}" @click="mode='login'">{{ tr('登录','Sign in') }}</button><button type="button" :disabled="authBusy" :class="{active:mode==='register'}" @click="mode='register'">{{ tr('邀请注册','Register') }}</button></div>
        <label>{{ tr('邮箱','Email') }}<input v-model.trim="email" :disabled="authBusy" type="email" required autocomplete="email" maxlength="254"></label>
        <label v-if="mode==='register'">{{ tr('邀请码','Invitation code') }}<input v-model.trim="invite" :disabled="authBusy" required maxlength="128" autocomplete="off"></label>
        <label>{{ tr('密码','Password') }}<input v-model="password" :disabled="authBusy" type="password" required :minlength="mode==='register'?12:undefined" :autocomplete="mode==='register'?'new-password':'current-password'"><small v-if="mode==='register'" class="hint">{{ tr('密码至少 12 位。','Use a password of at least 12 characters.') }}</small></label>
        <button type="submit" :disabled="authBusy">{{ authBusy?tr('请稍候…','Please wait…'):mode==='register'?tr('注册','Register'):tr('登录','Sign in') }}</button>
      </form>
      <p v-if="authError" class="account-error" role="alert">{{ authError }}</p>
    </section>
    <section ref="alertPanel" class="panel alert-settings">
      <div class="panel-head"><h2>{{ tr('提醒设置','Alert settings') }}</h2><span v-if="account.session" class="setting-status" :class="{'account-error':['error','health-error','delayed','service-unavailable'].includes(deliveryState)}">{{ deliveryLabel }}</span></div>
      <p class="hint">{{ tr('规则统一应用于账号的全部关注，不受当前页面网络筛选影响。','Rules apply to all followed items on your account, regardless of this page’s chain filter.') }}</p>
      <p v-if="!account.session" class="hint">{{ tr('登录后可绑定 Telegram 并管理提醒。','Sign in to link Telegram and manage alerts.') }}</p>
      <template v-else>
        <p v-if="telegramState==='loading'" class="hint" role="status">{{ tr('正在读取 Telegram 状态…','Loading Telegram status…') }}</p>
        <p v-else-if="telegramState==='error'" class="account-error" role="alert">{{ tr('Telegram 状态读取失败，绑定状态尚未确认。','Telegram status could not be loaded; your binding is unconfirmed.') }} <button type="button" @click="refreshTelegram">{{ tr('重试','Retry') }}</button></p>
        <template v-else-if="telegram">
          <p class="hint">{{ telegram.linked?tr('Telegram 已绑定。','Telegram linked.'):telegram.available?tr('尚未绑定 Telegram。','Telegram is not linked yet.'):tr('Telegram 渠道尚未开通，规则可先保存。','Telegram is not available yet; you can still save your rules.') }}</p>
          <div v-if="telegram.available" class="account-actions"><button v-if="!telegram.linked" :disabled="telegramBusy" @click="bindTelegram">{{ telegramBusy?tr('处理中…','Working…'):tr('绑定 Telegram','Link Telegram') }}</button><button v-else :disabled="telegramBusy" @click="unlinkTelegram">{{ tr('解除绑定','Unlink') }}</button><button type="button" :disabled="telegramBusy" @click="refreshTelegram">{{ tr('刷新状态','Refresh status') }}</button><a v-if="binding" :href="binding.startUrl" target="_blank" rel="noopener">{{ tr('打开机器人并点击 Start（10 分钟内）','Open bot and tap Start (within 10 minutes)') }} ↗</a></div>
          <p v-if="telegram.linked && healthState==='error'" class="account-error" role="alert">{{ tr('提醒运行状态读取失败，无法确认发送服务。','Delivery status could not be loaded; the sending service is unconfirmed.') }} <button type="button" @click="refreshTelegram">{{ tr('重试','Retry') }}</button></p>
          <p v-else-if="telegram.linked && ['delayed','service-unavailable'].includes(deliveryState)" class="hint">{{ tr('发送服务暂不可用，已保存规则仍然保留。','The sending service is currently unavailable. Your saved rules are retained.') }} <button type="button" @click="refreshTelegram">{{ tr('重新检查','Check again') }}</button></p>
          <p v-if="telegramError" class="account-error" role="alert">{{ telegramError }}</p>
        </template>
        <p v-if="preferenceState==='loading'" role="status" class="hint">{{ tr('正在读取提醒规则…','Loading alert rules…') }}</p>
        <p v-else-if="preferenceState==='error'" role="alert" class="account-error">{{ tr('提醒规则读取失败。','Alert rules could not be loaded.') }} <button type="button" @click="loadPreferences">{{ tr('重试','Retry') }}</button></p>
        <template v-else-if="preferences">
          <p v-if="alertTarget" class="hint">{{ alertTarget.label }} · {{ account.watches.includes(alertTarget.key)?tr('已关注','Followed'):tr('尚未关注','Not followed') }} <button v-if="!account.watches.includes(alertTarget.key)" type="button" @click="account.toggle(alertTarget.key)">{{ tr('关注此对象','Follow this item') }}</button></p>
          <form class="account-form" @change="saved=false" @submit.prevent="savePreferences">
            <fieldset :disabled="preferenceBusy"><label class="check-row"><input v-model="preferences.newPool" type="checkbox">{{ tr('新池子','New pools') }}</label><label class="check-row"><input v-model="preferences.riskChange" type="checkbox">{{ tr('风险变化','Risk changes') }}</label><template v-if="largeTradeAvailable"><label class="check-row"><input v-model="preferences.largeTrade" type="checkbox">{{ tr('大额成交','Large trades') }}</label><label>{{ tr('成交金额门槛（USD）','Trade threshold (USD)') }}<input v-model.number="preferences.tradeUsd" type="number" min="100" max="1000000000" step="100" :disabled="!preferences.largeTrade"></label></template><p v-else class="hint">{{ tr('大额成交提醒尚未开通。','Large-trade alerts are not available yet.') }}</p></fieldset>
            <div class="save-rule"><button :disabled="preferenceBusy">{{ preferenceBusy?tr('保存中…','Saving…'):tr('保存规则','Save rules') }}</button><span role="status">{{ preferenceBusy?'':saved?tr('已保存','Saved'):tr('修改后请保存','Save after editing') }}</span></div><p v-if="preferenceError" class="account-error" role="alert">{{ preferenceError }}</p>
          </form>
        </template>
        <details class="alert-health"><summary>{{ tr('最近发送与提醒预览','Recent delivery and preview') }}</summary><p class="hint">{{ tr('同一资产同类提醒间隔 15 分钟，每日最多 20 条。预览不会发送消息。','Same-type alerts for an asset have a 15-minute cooldown, with at most 20 alerts per day. Preview sends no messages.') }}</p><p v-if="telegramHealth?.worker?.updatedAt" class="hint">{{ tr('服务状态更新','Service status updated') }} {{ date(telegramHealth.worker.updatedAt) }}</p><p v-if="latestDelivery" class="hint">{{ tr('最近发送','Latest delivery') }}：{{ deliveryResult(latestDelivery.status) }} · {{ date(latestDelivery.finished_at || latestDelivery.created_at) }}</p><p v-else-if="healthState==='ready'" class="hint">{{ tr('暂无发送记录。','No delivery records yet.') }}</p><p v-if="account.session.operator && telegramHealth" class="hint">{{ tr('账号排队中','Queued for this account') }} {{ telegramHealth.queue?.pending ?? 0 }} · {{ tr('发送成功','Sent successfully') }} {{ telegramHealth.queue?.sent ?? 0 }}</p>
          <form v-if="assetWatches.length" class="account-form" @submit.prevent="previewAlert"><label>{{ tr('关注资产','Followed asset') }}<select v-model="previewAsset" :disabled="previewBusy"><option v-for="key in assetWatches" :key="key" :value="key">{{ previewName(key) }}</option></select></label><label>{{ tr('提醒类型','Alert type') }}<select v-model="previewCategory" :disabled="previewBusy"><option value="newPool">{{ tr('新池子','New pool') }}</option><option value="riskChange">{{ tr('风险变化','Risk change') }}</option></select></label><button :disabled="previewBusy">{{ previewBusy?tr('读取预览…','Loading preview…'):tr('预览提醒','Preview alert') }}</button></form><p v-else class="hint">{{ tr('关注一个资产后可预览提醒。','Follow an asset to preview its alerts.') }}</p><p v-if="previewError" class="account-error" role="alert">{{ previewError }}</p><pre v-if="alertPreview?.text" class="alert-preview">{{ alertPreview.text }}</pre><p v-if="alertPreview" class="hint">{{ tr('仅预览，不会排队或发送。','Preview only; nothing is queued or sent.') }} {{ alertPreview.eligible?'':previewReason(alertPreview.reason) }}</p>
        </details>
      </template>
    </section>
    <section class="panel display-preferences"><div class="panel-head"><h2>{{ tr('显示偏好','Display preferences') }}</h2><span class="setting-status">{{ tr('仅此设备','This device only') }}</span></div><p class="hint">{{ tr('外观、涨跌颜色和语言保存在当前设备。','Appearance, price colors and language are saved on this device.') }}</p><div class="account-form"><label>{{ tr('外观','Appearance') }}<select :value="displayPreferences.theme" @change="setDisplayPreference('theme',$event.target.value)"><option value="system">{{ tr('跟随系统','Follow system') }}</option><option value="light">{{ tr('浅色','Light') }}</option><option value="dark">{{ tr('深色','Dark') }}</option></select></label><label>{{ tr('涨跌颜色','Price change colors') }}<select :value="displayPreferences.gainColor" @change="setDisplayPreference('gainColor',$event.target.value)"><option value="green">{{ tr('绿涨红跌','Green up, red down') }}</option><option value="red">{{ tr('红涨绿跌','Red up, green down') }}</option></select></label><label>{{ tr('语言','Language') }}<select :value="lang.lang" @change="setLang($event.target.value)"><option value="zh">中文</option><option value="en">English</option></select></label></div></section>
    <section class="panel account-tools"><div class="panel-head"><h2>{{ tr('工具','Tools') }}</h2><RouterLink :to="pageNavigationLink('/developer',{route,scope})">{{ tr('API 文档与密钥','API docs and keys') }} →</RouterLink></div><WalletProfile /></section>
    <AliasReview v-if="account.session?.operator" />
  </div>
</template>
<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {tr,setLang,useI18n} from '../i18n';
import {useAccountStore} from '../stores/account';
import {developerRequest,loginDeveloper,registerDeveloper} from '../api/developer';
import {getDetail} from '../api/client';
import WalletProfile from '../components/WalletProfile.vue';
import AliasReview from '../components/AliasReview.vue';
import {readProductPreferences,setProductPreference} from '../utils/product-preferences';
import {telegramDeliveryState} from '../utils/account-status';
import {chainScope} from '../utils/chain-scope';
import {chainName,date,short} from '../utils/format';
import {pageNavigationLink} from '../utils/navigation-context';
import {clearPageState} from '../utils/page-navigation-state';
const account=useAccountStore(),route=useRoute(),router=useRouter(),{lang}=useI18n();
const scope=computed(()=>chainScope(route.query));
const displayPreferences=ref(readProductPreferences());
function setDisplayPreference(key,value){displayPreferences.value=setProductPreference(key,value);}
const refreshDisplay=()=>{displayPreferences.value=readProductPreferences();};
function refreshVisibleStatus(){if(!document.hidden&&account.session&&Date.now()-telegramCheckedAt>=60000&&telegramState.value!=='loading'&&!telegramBusy.value)refreshTelegram();}
const alertPanel=ref(null),telegram=ref(null),telegramHealth=ref(null),binding=ref(null),healthReadAt=ref(0),clock=ref(Date.now());
const telegramState=ref('idle'),healthState=ref('idle'),telegramError=ref(''),telegramBusy=ref(false);
const mode=ref('login'),email=ref(''),password=ref(''),invite=ref(''),authBusy=ref(false),authError=ref('');
const preferences=ref(null),deliveryPreferences=ref(null),saved=ref(false),preferenceState=ref('idle'),preferenceError=ref(''),preferenceBusy=ref(false);
const previewAsset=ref(''),previewCategory=ref('newPool'),alertPreview=ref(null),previewBusy=ref(false),previewError=ref(''),assetNames=ref({});
let preferenceRequest=0,telegramRequest=0,previewRequest=0,nameRequest=0,saveRequest=0,authRequest=0,telegramMutation=0,clockTimer,telegramCheckedAt=0;
const assetWatches=computed(()=>account.watches.filter(key=>/^\d+:0x[a-f0-9]{40}$/.test(key)));
const alertTarget=computed(()=>{const ticker=String(route.query.ticker||'').toUpperCase(),chain=String(route.query.chain||''),token=String(route.query.token||'').toLowerCase();if(route.query.kind==='alert'&&/^[A-Z0-9.^-]{1,24}$/.test(ticker))return {key:'stock:'+ticker,label:ticker};if(route.query.kind==='alert'&&/^[1-9]\d{0,9}$/.test(chain)&&/^0x[a-f0-9]{40}$/.test(token))return {key:chain+':'+token,label:chainName({chainId:chain})+' · '+short(token)};return null;});
const syncLabel=computed(()=>account.syncState==='loading'?tr('正在读取关注…','Loading follows…'):account.syncState==='saving'?tr('正在同步关注…','Syncing follows…'):account.syncState==='error'?account.error==='limit'?tr('关注已达账号上限，修改尚未同步。','Your watchlist limit is reached; edits are not synced.'):tr('已登录；关注暂未同步，修改保留在此设备。','Signed in; follows are not synced yet. Edits remain on this device.'):tr('关注已同步到账号','Follows synced to your account'));
const largeTradeAvailable=computed(()=>telegram.value?.capabilities?.largeTrade?.available===true);
const deliveryState=computed(()=>telegramDeliveryState({telegram:telegram.value,health:telegramHealth.value,preferences:deliveryPreferences.value,loading:telegramState.value==='loading',error:telegramState.value==='error',healthError:healthState.value==='error',now:clock.value,healthReadAt:healthReadAt.value}));
const deliveryLabel=computed(()=>({loading:tr('读取中…','Loading…'),error:tr('状态未确认','Status unconfirmed'),unavailable:tr('尚未开通','Not available'),unlinked:tr('未绑定','Not linked'),paused:tr('已暂停提醒','Alerts paused'),'rules-unconfirmed':tr('已绑定 · 规则未确认','Linked · rules unconfirmed'),'health-error':tr('已绑定 · 运行状态未知','Linked · service unconfirmed'),delayed:tr('已绑定 · 服务状态延迟','Linked · delayed service status'),'service-unavailable':tr('已绑定 · 发送暂不可用','Linked · delivery unavailable'),ready:tr('已绑定 · 发送服务运行中','Linked · delivery service active')})[deliveryState.value]);
const latestDelivery=computed(()=>telegramHealth.value?.recent?.[0]??null);
const deliveryResult=state=>({sent:tr('已发送','Sent'),pending:tr('待发送','Pending'),sending:tr('处理中','Processing'),failed:tr('发送失败','Failed'),unknown:tr('结果未确认','Outcome unconfirmed'),skipped:tr('未发送','Not sent')})[state]??tr('结果未确认','Outcome unconfirmed');
function failure(e,authentication=false){if(e?.message==='invalid-invitation')return tr('邀请码无效，请核对后重试。','Invalid invitation code. Check it and try again.');if(e?.message==='weak-password')return tr('密码至少需要 12 位。','Password must have at least 12 characters.');if(authentication&&e?.status===409)return tr('此邮箱已注册，请直接登录。','This email is registered. Sign in instead.');if(e?.status===401)return authentication?tr('邮箱或密码不正确。','Incorrect email or password.'):tr('登录已过期，请重新确认登录状态。','Your session expired. Check your session again.');if(e?.status===429)return tr('操作过于频繁，请稍后再试。','Too many attempts. Please try later.');return tr('暂时无法读取，请重试。','Could not load. Please retry.');}
async function submit(){if(authBusy.value)return;const request=++authRequest;authBusy.value=true;authError.value='';let session;try{session=mode.value==='register'?await registerDeveloper(email.value,invite.value,password.value):await loginDeveloper(email.value,password.value);}catch(e){if(request===authRequest)authError.value=failure(e,true);}if(session&&request===authRequest){password.value='';try{await account.useSession(session);}catch{/* Authentication and follow synchronization are independent. */}if(account.session?.user.id===session.user.id){const next=String(route.query.next??'');if(next.startsWith('/')&&!next.startsWith('//'))router.replace(next);}}if(request===authRequest)authBusy.value=false;}
async function signOut(){if(authBusy.value)return;const id=account.session?.user.id,request=++authRequest;authBusy.value=true;authError.value='';try{await account.logout();if(id!=null)clearPageState(`wallet-profile:${id}`);clearPageState('wallet-profile:guest');}catch(e){if(request===authRequest)authError.value=failure(e);}finally{if(request===authRequest)authBusy.value=false;}}
async function savePreferences(){const id=account.session?.user.id;if(!id||!preferences.value||preferenceBusy.value)return;const request=++saveRequest,body={newPool:!!preferences.value.newPool,riskChange:!!preferences.value.riskChange,largeTrade:!!preferences.value.largeTrade,tradeUsd:Number(preferences.value.tradeUsd)};preferenceBusy.value=true;saved.value=false;preferenceError.value='';try{const result=await developerRequest('alerts',{method:'PUT',body,csrfToken:account.session.csrfToken});if(request===saveRequest&&account.session?.user.id===id){preferences.value=result;deliveryPreferences.value={...body};saved.value=true;}}catch(e){if(request===saveRequest&&account.session?.user.id===id)preferenceError.value=failure(e);}finally{if(request===saveRequest)preferenceBusy.value=false;}}
async function loadPreferences(){const id=account.session?.user.id;if(!id)return;const request=++preferenceRequest;preferenceState.value='loading';preferenceError.value='';try{const value=await developerRequest('alerts');if(request===preferenceRequest&&account.session?.user.id===id){preferences.value=value;deliveryPreferences.value={newPool:value.newPool,riskChange:value.riskChange,largeTrade:value.largeTrade};preferenceState.value='ready';}}catch(e){if(request===preferenceRequest&&account.session?.user.id===id){preferenceState.value='error';preferenceError.value=failure(e);}}}
async function refreshTelegram(){const id=account.session?.user.id;if(!id)return;const request=++telegramRequest;telegramCheckedAt=Date.now();telegramState.value='loading';healthState.value='loading';telegramError.value='';const results=await Promise.allSettled([developerRequest('telegram'),developerRequest('telegram/health')]);if(request!==telegramRequest||account.session?.user.id!==id)return;const [status,health]=results;if(status.status==='fulfilled'){telegram.value=status.value;telegramState.value='ready';if(status.value.linked)binding.value=null;}else{telegramState.value='error';telegramError.value=failure(status.reason);}if(health.status==='fulfilled'){telegramHealth.value=health.value;healthReadAt.value=Date.now();healthState.value='ready';}else healthState.value='error';}
async function bindTelegram(){const id=account.session?.user.id;if(!id||telegramBusy.value)return;const request=++telegramMutation;telegramBusy.value=true;telegramError.value='';try{const value=await developerRequest('telegram/bind',{method:'POST',csrfToken:account.session.csrfToken});if(request===telegramMutation&&account.session?.user.id===id)binding.value=value;}catch(e){if(request===telegramMutation&&account.session?.user.id===id)telegramError.value=failure(e);}finally{if(request===telegramMutation)telegramBusy.value=false;}}
async function unlinkTelegram(){const id=account.session?.user.id;if(!id||telegramBusy.value)return;const request=++telegramMutation;telegramBusy.value=true;telegramError.value='';try{await developerRequest('telegram',{method:'DELETE',csrfToken:account.session.csrfToken});if(request===telegramMutation&&account.session?.user.id===id){binding.value=null;await refreshTelegram();}}catch(e){if(request===telegramMutation&&account.session?.user.id===id)telegramError.value=failure(e);}finally{if(request===telegramMutation)telegramBusy.value=false;}}
function previewReason(reason){return reason==='no-triggered-risk'?tr('当前没有已触发的风险项。','No triggered risk checks.'):reason==='event-outside-15-minute-window'?tr('事件超过 15 分钟，不会触发历史提醒。','This event is over 15 minutes old and will not trigger a historical alert.'):tr('当前没有满足来源条件的事件。','No event meets the source requirements.');}
function previewName(key){const [chainId,token]=key.split(':');return [assetNames.value[key],chainName({chainId}),short(token)].filter(Boolean).join(' · ');}
async function previewAlert(){const id=account.session?.user.id;if(!id||previewBusy.value)return;const request=++previewRequest;previewBusy.value=true;previewError.value='';alertPreview.value=null;try{const value=await developerRequest('telegram/dry-run',{method:'POST',body:{category:previewCategory.value,assetKey:previewAsset.value},csrfToken:account.session.csrfToken});if(request===previewRequest&&account.session?.user.id===id)alertPreview.value=value;}catch(e){if(request===previewRequest&&account.session?.user.id===id)previewError.value=failure(e);}finally{if(request===previewRequest)previewBusy.value=false;}}
watch(assetWatches,keys=>{const target=alertTarget.value?.key;if(target&&keys.includes(target))previewAsset.value=target;else if(!keys.includes(previewAsset.value))previewAsset.value=keys[0]||'';},{immediate:true});
watch([previewAsset,previewCategory],()=>{++previewRequest;previewBusy.value=false;alertPreview.value=null;previewError.value='';});
watch([previewAsset,()=>account.session?.user.id],async ([key])=>{await nextTick();const request=++nameRequest,id=account.session?.user.id;if(!key||assetNames.value[key])return;const [chain,token]=key.split(':');try{const result=await getDetail(chain,token,{section:'overview'});if(request===nameRequest&&account.session?.user.id===id&&String(result.asset?.chainId??chain)===chain&&String(result.asset?.token??'').toLowerCase()===token)assetNames.value={...assetNames.value,[key]:result.asset.name||result.asset.symbol};}catch{/* Chain and short contract remain a precise fallback. */}},{immediate:true});
watch([()=>account.session?.user.id,()=>route.query.kind],async()=>{if(route.query.kind==='alert'&&account.session){await nextTick();alertPanel.value?.scrollIntoView({behavior:'smooth',block:'start'});}},{immediate:true});
watch(()=>account.session?.user.id,id=>{++preferenceRequest;++telegramRequest;++previewRequest;++nameRequest;++saveRequest;++telegramMutation;preferences.value=null;deliveryPreferences.value=null;telegram.value=null;telegramHealth.value=null;healthReadAt.value=0;alertPreview.value=null;binding.value=null;assetNames.value={};saved.value=false;preferenceBusy.value=false;telegramBusy.value=false;previewBusy.value=false;preferenceState.value='idle';telegramState.value='idle';healthState.value='idle';preferenceError.value='';telegramError.value='';previewError.value='';if(id){loadPreferences();refreshTelegram();}},{immediate:true});
onMounted(()=>{window.addEventListener('storage',refreshDisplay);window.addEventListener('product-preferences-change',refreshDisplay);document.addEventListener('visibilitychange',refreshVisibleStatus);clockTimer=setInterval(()=>{if(!document.hidden){clock.value=Date.now();refreshVisibleStatus();}},5000);});
onUnmounted(()=>{++authRequest;++preferenceRequest;++telegramRequest;++previewRequest;++nameRequest;++saveRequest;++telegramMutation;clearInterval(clockTimer);window.removeEventListener('storage',refreshDisplay);window.removeEventListener('product-preferences-change',refreshDisplay);document.removeEventListener('visibilitychange',refreshVisibleStatus);});
account.start();
</script>
